class Solution {
public:
    int subsequencePairCount(vector<int>& nums) {
        const int MOD = 1000000007;
        int max_val = 0;
        for (int v : nums) max_val = max(max_val, v);

        vector<vector<int>> dp(max_val + 1, vector<int>(max_val + 1, 0));
        dp[0][0] = 1;

        for (int x : nums) {
            auto new_dp = dp;
            for (int g1 = 0; g1 <= max_val; ++g1) {
                for (int g2 = 0; g2 <= max_val; ++g2) {
                    if (!dp[g1][g2]) continue;
                    int cnt = dp[g1][g2];

                    int ng1 = std::gcd(g1, x);
                    new_dp[ng1][g2] = (new_dp[ng1][g2] + cnt) % MOD;

                    int ng2 = std::gcd(g2, x);
                    new_dp[g1][ng2] = (new_dp[g1][ng2] + cnt) % MOD;
                }
            }
            dp = std::move(new_dp);
        }

        long long ans = 0;
        for (int g = 1; g <= max_val; ++g) {
            ans = (ans + dp[g][g]) % MOD;
        }
        return ans;
    }
};

class Solution {
    public int subsequencePairCount(int[] nums) {
        int MOD = 1_000_000_007;
        int maxVal = 0;
        for (int v : nums) maxVal = Math.max(maxVal, v);

        int[][] dp = new int[maxVal + 1][maxVal + 1];
        dp[0][0] = 1;

        for (int x : nums) {
            int[][] newDp = new int[maxVal + 1][maxVal + 1];
            for (int i = 0; i <= maxVal; i++) {
                System.arraycopy(dp[i], 0, newDp[i], 0, maxVal + 1);
            }
            for (int g1 = 0; g1 <= maxVal; g1++) {
                for (int g2 = 0; g2 <= maxVal; g2++) {
                    if (dp[g1][g2] == 0) continue;
                    int cnt = dp[g1][g2];

                    int ng1 = gcd(g1, x);
                    newDp[ng1][g2] = (newDp[ng1][g2] + cnt) % MOD;

                    int ng2 = gcd(g2, x);
                    newDp[g1][ng2] = (newDp[g1][ng2] + cnt) % MOD;
                }
            }
            dp = newDp;
        }

        long ans = 0;
        for (int g = 1; g <= maxVal; g++) {
            ans = (ans + dp[g][g]) % MOD;
        }
        return (int) ans;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

