                const ng2 = gcd(g2, x);
                newDp[g1][ng2] = (newDp[g1][ng2] + cnt) % MOD;
            }
        }
        dp = newDp;
    }

    let ans = 0;
    for (let g = 1; g <= maxVal; g++) {
        ans = (ans + dp[g][g]) % MOD;
